package dev.vantara.replicatorops.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class GcodeOutlinesTest {
    private val gcode = """
        ; generated by QIDIStudio
        EXCLUDE_OBJECT_DEFINE NAME=Cube_id_0_copy_0 CENTER=10,10
        EXCLUDE_OBJECT_DEFINE NAME=Ring_id_1_copy_0 CENTER=50,50
        G90
        M83
        G1 Z0.2 F600
        EXCLUDE_OBJECT_START NAME=Cube_id_0_copy_0
        G1 X0 Y0 F3000
        G1 X20 Y0 E1.0
        G1 X20 Y20 E1.0
        G1 X0 Y20 E1.0
        G1 X0 Y0 E1.0
        EXCLUDE_OBJECT_END NAME=Cube_id_0_copy_0
        EXCLUDE_OBJECT_START NAME=Ring_id_1_copy_0
        G1 X40 Y40
        G1 X60 Y40 E1
        G1 X60 Y60 E1
        EXCLUDE_OBJECT_END NAME=Ring_id_1_copy_0
        G1 Z1.2
        EXCLUDE_OBJECT_START NAME=Cube_id_0_copy_0
        G1 X100 Y100 E1
        EXCLUDE_OBJECT_END NAME=Cube_id_0_copy_0
        EXCLUDE_OBJECT_START NAME=Ring_id_1_copy_0
        G1 X120 Y120 E1
        EXCLUDE_OBJECT_END NAME=Ring_id_1_copy_0
        G1 X200 Y200 E5
    """.trimIndent()

    @Test fun firstLayerPerObject() {
        val o = GcodeOutlines.parse(gcode.byteInputStream())
        assertEquals(setOf("Cube_id_0_copy_0", "Ring_id_1_copy_0"), o.keys)
        val cube = o.getValue("Cube_id_0_copy_0")
        assertEquals(4 * 4, cube.segments.size)          // four extruding moves, travel skipped
        assertEquals(4, cube.hull.size)                    // a square
        assertFalse(cube.segments.any { it >= 100f })      // upper layer ignored
        assertTrue(o.getValue("Ring_id_1_copy_0").segments.size == 8)
    }
}
